<style>
    .workspace-shell:has([data-media-results]) .workspace-sidebar { background:#111318; }
    .workspace-shell:has([data-media-results]) .workspace-main { background:#f7f7f8; }
    [data-theme="dark"] .workspace-shell:has([data-media-results]) .workspace-main { background:#111318; }
    .media-view-toggle a { background:var(--surface); color:var(--ink); }
    .media-view-toggle a.is-active { background:var(--ink); color:var(--surface); }
    .media-upload-panel { overflow:hidden; }
    .media-upload-panel form { display:grid; gap:10px; }
    .media-dropzone { display:grid; min-height:112px; place-items:center; border:1px dashed var(--line-strong); border-radius:12px; background:var(--surface-muted); text-align:center; cursor:pointer; }
    .media-dropzone strong { display:block; color:var(--ink); font-size:.7rem; }
    .media-dropzone small { display:block; margin-top:5px; color:var(--muted); font-size:.6rem; }
    .media-dropzone[data-selected="true"] { border-style:solid; border-color:var(--line-strong); background:var(--surface); }
    .media-dropzone[data-selected="true"] small { color:var(--ink); font-weight:700; }
    .media-dropzone input { position:absolute; width:1px; height:1px; opacity:0; }
    .media-upload-panel input[type=file] { min-width:0; max-width:100%; font-size:.68rem; }
    .media-upload-panel button { white-space:nowrap; }
    .media-search { display:flex; gap:8px; align-items:center; margin-bottom:14px; }
    .media-search input { width:min(360px,100%); }
    .media-toolbar .media-search input, .media-toolbar .media-search select, .media-toolbar .media-search button { height:42px !important; min-height:42px !important; box-sizing:border-box !important; margin:0 !important; }
    .media-toolbar .media-search input { border:1px solid var(--line-strong) !important; border-radius:9px !important; background:var(--surface) !important; color:var(--ink) !important; padding:0 10px !important; }
    .media-search .enhanced-select { flex:0 1 148px; min-width:0; max-width:100%; }
    .media-search .enhanced-select-trigger { height:42px; min-height:42px; border:1px solid var(--line-strong); border-radius:9px; background:var(--surface); color:var(--ink); padding:0 10px; font:inherit; font-size:.66rem; box-shadow:none; }
    .media-search .enhanced-select-trigger:hover, .media-search .enhanced-select.is-open .enhanced-select-trigger, .media-search .enhanced-select-trigger:focus-visible { border-color:var(--line-strong); box-shadow:0 0 0 3px color-mix(in srgb,var(--ink) 10%,transparent); }
    .media-search .enhanced-select-options { min-width:100%; max-width:min(260px,calc(100vw - 24px)); }
    .media-toolbar .media-search button { display:inline-flex; align-items:center; justify-content:center; padding:0 14px !important; }
    [data-media-results] { min-width:0; max-width:100%; overflow:hidden; }
    .media-toolbar { display:flex; min-width:0; max-width:100%; justify-content:space-between; align-items:flex-start; gap:10px; margin:14px 0; }
    .media-search { min-width:0; max-width:100%; flex:1 1 auto; }
    .media-search input, .media-search select, .media-search button { min-width:0; max-width:100%; box-sizing:border-box; }
    .media-toolbar .media-view-toggle { flex:0 0 auto; }
    .media-view-toggle { display:flex; gap:4px; padding:3px; border:1px solid var(--line); border-radius:9px; background:var(--surface); }
    .media-view-toggle a { display:inline-flex; height:32px; box-sizing:border-box; align-items:center; padding:0 11px; border-radius:6px; color:var(--muted); font-size:.6rem; text-decoration:none; }
    .media-view-toggle a.is-active { background:var(--surface-muted); color:var(--ink); font-weight:750; }
    .media-grid { display:grid; grid-template-columns:repeat(auto-fill,minmax(155px,1fr)); gap:10px; }
    .media-card { min-width:0; overflow:hidden; border:1px solid var(--line); border-radius:12px; background:var(--surface); }
    .media-card-preview { display:grid; height:112px; place-items:center; background:var(--surface-muted); color:var(--muted); }
    .media-card-preview strong { font-size:1.5rem; font-weight:760; text-transform:uppercase; }
    .media-card-body { padding:10px; }
    .media-card-body strong { display:block; overflow:hidden; color:var(--ink); font-size:.66rem; text-overflow:ellipsis; white-space:nowrap; }
    .media-card-body small { display:block; margin-top:4px; color:var(--muted); font-size:.56rem; }
    .media-list-name { display:block; color:var(--ink); font-size:.7rem; font-weight:700; }
    .media-list-status { display:flex; align-items:center; justify-content:space-between; gap:8px; min-width:140px; }
    .media-list-edit { min-height:30px !important; height:30px !important; padding:0 10px !important; border-radius:8px !important; font-size:.6rem !important; }
    .media-card { cursor:pointer; }
    .media-details-modal { position:fixed; inset:0; z-index:80; display:none; place-items:center; padding:18px; background:rgb(15 23 20 / 48%); }
    .media-details-modal.is-open { display:grid; }
    .media-details-card { width:min(620px,100%); max-height:min(760px,90vh); overflow:auto; border:1px solid var(--line-strong); border-radius:16px; background:var(--surface); box-shadow:0 24px 70px rgb(0 0 0 / 20%); }
    .media-details-head { display:flex; align-items:center; justify-content:space-between; gap:10px; padding:15px 17px; border-bottom:1px solid var(--line); }
    .media-details-head h2 { margin:0; color:var(--ink); font-size:.86rem; }
    .media-details-body { display:grid; gap:11px; padding:17px; }
    .media-details-body label { display:grid; gap:5px; color:var(--muted); font-size:.62rem; font-weight:700; }
    .media-details-body input, .media-details-body textarea { width:100%; min-width:0; box-sizing:border-box; border:1px solid var(--line-strong); border-radius:9px; background:var(--surface); color:var(--ink); padding:9px 10px; font:inherit; font-size:.72rem; line-height:1.35; outline:none; transition:border-color .15s ease, box-shadow .15s ease, background .15s ease; }
    .media-details-body input:hover, .media-details-body textarea:hover { border-color:var(--muted); }
    .media-details-body input:focus, .media-details-body textarea:focus { border-color:var(--accent); box-shadow:0 0 0 3px color-mix(in srgb, var(--accent) 18%, transparent); }
    .media-details-body textarea { min-height:86px; }
    .media-details-body textarea { min-height:70px; resize:vertical; }
    .media-details-actions { display:flex; justify-content:flex-end; gap:8px; padding:0 17px 17px; }
    @media (max-width:680px) {
        .media-toolbar { display:grid; grid-template-columns:minmax(0,1fr) auto; align-items:start; }
        .media-search { grid-column:1 / -1; }
        .media-upload-panel form { grid-template-columns:1fr !important; gap:9px !important; }
        .media-upload-panel button { width:100%; }
        .media-search { display:grid; grid-template-columns:1fr auto; }
        .media-search button { min-height:38px; }
    }
</style>
