    <div class="media-details-modal" data-media-modal aria-hidden="true"><div class="media-details-card" role="dialog" aria-modal="true" aria-labelledby="media-details-title"><div class="media-details-head"><h2 id="media-details-title">Media details</h2><button type="button" class="button button-secondary" data-media-close aria-label="Close details">Close</button></div><form method="POST" data-media-form class="media-details-body">@csrf @method('PATCH')<label>Title<input name="title" required></label><label>Filename<input name="file_name" required></label><label>Alt text<input name="alt_text" maxlength="180"></label><label>Caption<input name="caption" maxlength="255"></label><label>Description<textarea name="description" maxlength="5000"></textarea></label><div class="media-details-actions"><button type="button" class="button button-secondary" data-media-close>Cancel</button><button type="button" class="button button-secondary" data-media-delete>Delete</button><button type="submit" class="button">Save details</button></div></form></div></div>
    <script>const mediaInput=document.querySelector('[data-media-dropzone] input');if(mediaInput){mediaInput.addEventListener('change',()=>{const zone=mediaInput.closest('[data-media-dropzone]'),files=[...mediaInput.files];zone.dataset.selected=files.length?'true':'false';zone.querySelector('[data-media-file-title]').textContent=files.length?`${files.length} file${files.length===1?'':'s'} selected`:'Drop files here or choose files';zone.querySelector('[data-media-file-summary]').textContent=files.length?files.map((file)=>file.name).join(', '):'Images, videos, and documents · up to 100 MB each';});}document.querySelectorAll('[data-media-item]').forEach((item)=>item.addEventListener('click',()=>{const d=JSON.parse(item.dataset.mediaItem),m=document.querySelector('[data-media-modal]'),f=m.querySelector('[data-media-form]');f.action='{{ url('/staff/media-library') }}/'+d.id;['title','file_name','alt_text','caption','description'].forEach((k)=>{if(f.elements[k])f.elements[k].value=d[k]||''});m.classList.add('is-open');m.setAttribute('aria-hidden','false');f.elements.title.focus()}));document.querySelectorAll('[data-media-close]').forEach((b)=>b.addEventListener('click',()=>{const m=document.querySelector('[data-media-modal]');m.classList.remove('is-open');m.setAttribute('aria-hidden','true')}));</script>
<script>const uploadForm=document.querySelector('.media-upload-panel form');if(uploadForm){uploadForm.addEventListener('submit',async(event)=>{event.preventDefault();const button=uploadForm.querySelector('button[type="submit"]'),status=document.createElement('p');status.className='media-upload-status';status.setAttribute('role','status');status.textContent='Uploading…';uploadForm.after(status);button.disabled=true;try{const response=await fetch(uploadForm.action,{method:'POST',body:new FormData(uploadForm),headers:{'Accept':'application/json','X-Requested-With':'XMLHttpRequest'}});const payload=await response.json();if(!response.ok)throw new Error(payload.message||'Upload failed.');status.textContent=payload.message||'Upload complete.';window.dispatchEvent(new Event('media:changed'));uploadForm.reset();document.querySelector('[data-media-file-title]').textContent='Drop files here or choose files';document.querySelector('[data-media-file-summary]').textContent='Images, videos, and documents · up to 100 MB each';document.querySelector('[data-media-dropzone]').dataset.selected='false';}catch(error){status.textContent=error.message;}finally{button.disabled=false;}});}</script>
<script>(function(){const results=()=>document.querySelector('[data-media-results]');const enhance=(node)=>document.dispatchEvent(new CustomEvent('ministry:enhance-selects',{detail:node}));let busy=false;async function refresh(url){if(busy)return;busy=true;const target=results();target?.classList.add('is-loading');try{const response=await fetch(url,{headers:{'Accept':'text/html','X-Requested-With':'XMLHttpRequest'}});if(!response.ok)throw new Error('Could not refresh media.');const html=await response.text(),doc=new DOMParser().parseFromString(html,'text/html'),next=doc.querySelector('[data-media-results]');if(next&&target){target.replaceWith(next);enhance(next);history.replaceState({},'',url);}}catch(error){console.error(error);}finally{busy=false;results()?.classList.remove('is-loading');}}document.addEventListener('submit',event=>{const form=event.target.closest('.media-search');if(!form)return;event.preventDefault();refresh(`${form.action}?${new URLSearchParams(new FormData(form))}`);});document.addEventListener('click',event=>{const link=event.target.closest('.media-view-toggle a, [data-media-results] .pagination a');if(!link)return;event.preventDefault();refresh(link.href);});document.addEventListener('change',event=>{const control=event.target.closest('.media-search select');if(control){const form=control.form;refresh(`${form.action}?${new URLSearchParams(new FormData(form))}`);}});})();</script>
<style>[data-media-results].is-loading{opacity:.58;pointer-events:none;transition:opacity .15s ease}</style>
<script>(function(){document.addEventListener('submit',async(event)=>{const form=event.target.closest('[data-media-form]');if(!form)return;event.preventDefault();const button=form.querySelector('button[type="submit"]');button.disabled=true;try{const response=await fetch(form.action,{method:'POST',body:new FormData(form),headers:{'Accept':'application/json','X-Requested-With':'XMLHttpRequest'}});if(!response.ok)throw new Error('Could not save media details.');document.querySelector('[data-media-modal]')?.classList.remove('is-open');window.dispatchEvent(new Event('media:changed'));}catch(error){alert(error.message);}finally{button.disabled=false;}});window.addEventListener('media:changed',()=>{const url=window.location.href,results=document.querySelector('[data-media-results]');if(!results)return;fetch(url,{headers:{'Accept':'text/html','X-Requested-With':'XMLHttpRequest'}}).then(response=>response.text()).then(html=>{const next=new DOMParser().parseFromString(html,'text/html').querySelector('[data-media-results]');if(next){results.replaceWith(next);document.dispatchEvent(new CustomEvent('ministry:enhance-selects',{detail:next}));}});});})();</script>
<script>document.addEventListener("click",async(event)=>{const button=event.target.closest("[data-media-delete]");if(!button)return;const modal=document.querySelector("[data-media-modal]"),form=document.querySelector("[data-media-form]");if(!form||!confirm("Delete this media file?"))return;button.disabled=true;const response=await fetch(form.action,{method:"DELETE",headers:{"Accept":"application/json","X-Requested-With":"XMLHttpRequest","X-CSRF-TOKEN":document.querySelector("meta[name=csrf-token]")?.content||""}});if(response.ok){modal.classList.remove("is-open");window.dispatchEvent(new Event("media:changed"));}else{button.disabled=false;}});</script>
<script>document.addEventListener("click",(event)=>{const item=event.target.closest("[data-media-item]");if(item){const data=JSON.parse(item.dataset.mediaItem),modal=document.querySelector("[data-media-modal]"),form=document.querySelector("[data-media-form]");if(!modal||!form)return;form.action="/staff/media-library/"+data.id;["title","file_name","alt_text","caption","description"].forEach((key)=>{if(form.elements[key])form.elements[key].value=data[key]||""});modal.classList.add("is-open");modal.setAttribute("aria-hidden","false");form.elements.title?.focus();return;}const close=event.target.closest("[data-media-close]");if(close){const modal=document.querySelector("[data-media-modal]");modal?.classList.remove("is-open");modal?.setAttribute("aria-hidden","true");}});document.querySelectorAll(".media-card[data-media-item]").forEach((card)=>{const data=JSON.parse(card.dataset.mediaItem),mime=data.file_mime||"",preview=card.querySelector(".media-card-preview");if(!preview||!data.id)return;const url="/staff/media-library/"+data.id+"/file";if(mime.startsWith("image/")){preview.replaceChildren(Object.assign(document.createElement("img"),{src:url,alt:"",loading:"lazy"}));}else if(mime.startsWith("video/")){const video=Object.assign(document.createElement("video"),{src:url,muted:true,preload:"metadata"});preview.replaceChildren(video);}});</script>
<script>(function(){const enhance=()=>{document.querySelectorAll('.media-card[data-media-item]').forEach((card)=>{if(card.dataset.previewReady==='true')return;const data=JSON.parse(card.dataset.mediaItem||'{}'),mime=data.file_mime||'',preview=card.querySelector('.media-card-preview');if(!preview||!data.id)return;const url='/staff/media-library/'+data.id+'/file';if(mime.startsWith('image/')){const image=document.createElement('img');image.src=url;image.alt='';image.loading='lazy';image.onerror=()=>{image.remove();};preview.replaceChildren(image);}else if(mime.startsWith('video/')){const video=document.createElement('video');video.src=url;video.muted=true;video.preload='metadata';preview.replaceChildren(video);}card.dataset.previewReady='true';});};enhance();new MutationObserver(enhance).observe(document.body,{childList:true,subtree:true});})();</script>
</x-layouts.workspace>
